mapper.select:
SELECT r.app_role_id, r.company_id, r.role_code, r.role_name, r.role_type, r.description, r.use_yn, SUM( CASE WHEN rp.active_yn = 'Y' THEN 1 ELSE 0 END ) AS permission_count, 'N' AS assigned_yn FROM app_role r LEFT JOIN app_role_permission rp ON rp.app_role_id = r.app_role_id WHERE r.company_id = #{companyId}
AND ( LOWER(r.role_code) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(r.role_name) LIKE '%' || LOWER(#{keyword}) || '%' )
AND r.use_yn = #{useYn}
GROUP BY r.app_role_id, r.company_id, r.role_code, r.role_name, r.role_type, r.description, r.use_yn ORDER BY CASE r.role_type WHEN 'OWNER' THEN 0 ELSE 1 END, r.use_yn DESC, r.role_name ASC

mapper.update:
UPDATE app_role_permission
SET active_yn = 'N',
    updated_at = CAST(
        SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
        AS TIMESTAMP
    ),
    updated_by = #{updatedBy}
WHERE app_role_id = #{roleId}
  AND active_yn = 'Y'
